@page "/catalog"
@using sv_22d06df44a0643218896de5d3ca26d53.Models
@using sv_22d06df44a0643218896de5d3ca26d53.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

<div class="row">
    @* ───── Left Sidebar (Filters) ───── *@
    <div class="col-md-3">
        <div class="card">
            <div class="card-header fw-bold">Filters</div>
            <div class="card-body">

                @* Category checkboxes *@
                <h6>Category</h6>
                @if (categories is not null)
                {
                    @foreach (var cat in categories)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                                   checked="@selectedCategories.Contains(cat)"
                                   @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                            <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                        </div>
                    }
                }

                <hr />

                @* Price range *@
                <h6>Price Range</h6>
                <div class="mb-2">
                    <label class="form-label small mb-0">Min Price</label>
                    <input type="number" class="form-control form-control-sm" min="0"
                           @bind="minPrice" @bind:event="onchange" placeholder="0" />
                </div>
                <div class="mb-2">
                    <label class="form-label small mb-0">Max Price</label>
                    <input type="number" class="form-control form-control-sm" min="0"
                           @bind="maxPrice" @bind:event="onchange" placeholder="Any" />
                </div>

                <hr />

                @* In-stock toggle *@
                <div class="form-check mb-3">
                    <input class="form-check-input" type="checkbox" id="inStockOnly"
                           @bind="inStockOnly" />
                    <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                </div>

                @* Action buttons *@
                <button class="btn btn-primary btn-sm w-100 mb-2" @onclick="ApplyFilters">Apply Filters</button>
                <button class="btn btn-outline-secondary btn-sm w-100" @onclick="ClearFilters">Clear Filters</button>
            </div>
        </div>
    </div>

    @* ───── Main Content ───── *@
    <div class="col-md-9">

        @if (errorMessage is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @errorMessage
            </div>
        }
        else if (isLoading)
        {
            <div class="d-flex justify-content-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else if (result is not null)
        {
            @* Toolbar *@
            <div class="d-flex justify-content-between align-items-center mb-3">
                <div>
                    <label class="form-label small mb-0 me-1">Sort by</label>
                    <select class="form-select form-select-sm d-inline-block w-auto" @onchange="OnSortChanged">
                        @foreach (var opt in sortOptions)
                        {
                            <option value="@opt.Value" selected="@(sortBy == opt.Value)">@opt.Label</option>
                        }
                    </select>
                </div>
                <span class="text-muted small">
                    Showing @ShowingRange of @result.TotalCount products
                </span>
            </div>

            @if (result.Items.Count == 0)
            {
                <div class="alert alert-info text-center" role="alert">
                    No products match your filters. Try adjusting your search criteria.
                </div>
            }
            else
            {
                @* Product Grid *@
                <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3 mb-3">
                    @foreach (var product in result.Items)
                    {
                        <div class="col">
                            <ProductCard Product="product"
                                         OnProductSelected="HandleProductSelected"
                                         OnAddToCart="HandleAddToCart" />
                        </div>
                    }
                </div>

                @* Pagination *@
                @if (TotalPages > 1)
                {
                    <nav aria-label="Product pagination">
                        <ul class="pagination justify-content-center">
                            <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPage(currentPage - 1)">Previous</button>
                            </li>
                            @foreach (var p in GetPageNumbers())
                            {
                                <li class="page-item @(p == currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="() => GoToPage(p)">@p</button>
                                </li>
                            }
                            <li class="page-item @(currentPage == TotalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPage(currentPage + 1)">Next</button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        }
    </div>
</div>

@code {
    // ── State ──
    private List<string>? categories;
    private PagedResult<Product>? result;
    private bool isLoading = true;
    private string? errorMessage;

    // Filter state
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    // Pagination / sorting
    private int currentPage = 1;
    private const int PageSize = 9;
    private string sortBy = "price_asc";

    private static readonly (string Value, string Label)[] sortOptions =
    [
        ("price_asc",  "Price: Low to High"),
        ("price_desc", "Price: High to Low"),
        ("name_asc",   "Name: A-Z"),
        ("rating_desc","Rating: Highest"),
    ];

    // ── Lifecycle ──
    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    // ── Data loading ──
    private async Task LoadDataAsync()
    {
        try
        {
            isLoading = true;
            errorMessage = null;

            // Load categories and first page in parallel
            var categoriesTask = categories is null
                ? ProductService.GetCategoriesAsync()
                : Task.FromResult(categories);

            var filter = BuildFilter();
            var searchTask = ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);

            await Task.WhenAll(categoriesTask, searchTask);

            categories = await categoriesTask;
            result = await searchTask;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private ProductFilter BuildFilter() => new(
        Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
        MinPrice: minPrice,
        MaxPrice: maxPrice,
        InStockOnly: inStockOnly
    );

    // ── Filter actions ──
    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked) selectedCategories.Add(category);
        else selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadDataAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadDataAsync();
    }

    // ── Sort ──
    private async Task OnSortChanged(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await LoadDataAsync();
    }

    // ── Pagination ──
    private int TotalPages => result is null || result.PageSize == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / result.PageSize);

    private string ShowingRange
    {
        get
        {
            if (result is null || result.TotalCount == 0) return "0";
            int start = (result.Page - 1) * result.PageSize + 1;
            int end = Math.Min(result.Page * result.PageSize, result.TotalCount);
            return $"{start}\u2013{end}";
        }
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages || page == currentPage) return;
        currentPage = page;
        await LoadDataAsync();
    }

    private IEnumerable<int> GetPageNumbers()
    {
        const int maxVisible = 5;
        int start = Math.Max(1, currentPage - maxVisible / 2);
        int end = Math.Min(TotalPages, start + maxVisible - 1);
        start = Math.Max(1, end - maxVisible + 1);

        for (int i = start; i <= end; i++)
            yield return i;
    }

    // ── Card callbacks ──
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for cart integration
        return Task.CompletedTask;
    }
}

